def run(cmd, timeout=10):
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, check=False)
        return result.stdout
    except (OSError, subprocess.SubprocessError):
        return ""


def detect_network():
    """Detect the default IPv4 network, gateway, interface and local MAC."""
    out = run(["ip", "-4", "-o", "route", "show", "default"])
    match = re.search(r"default via (\S+) dev (\S+)", out)
    if not match:
        return None
    gateway, dev = match.group(1), match.group(2)
    out = run(["ip", "-4", "-o", "addr", "show", "dev", dev])
    match = re.search(r"inet (\S+)", out)
    if not match:
        return None
    try:
        iface = ipaddress.ip_interface(match.group(1))
    except ValueError:
        return None
    network = iface.network
    if network.prefixlen < 22:
        network = ipaddress.ip_network(f"{iface.ip}/24", strict=False)
    mac = ""
    try:
        with open(f"/sys/class/net/{dev}/address", encoding="utf-8") as handle:
            mac = handle.read().strip().upper()
    except OSError:
        pass
    return {"network": str(network), "ip": str(iface.ip), "gateway": gateway, "dev": dev, "mac": mac}


def arp_table():
    table = {}
    for line in run(["ip", "-4", "neigh"]).splitlines():
        match = re.match(r"(\d+\.\d+\.\d+\.\d+) .*lladdr ([0-9a-fA-F:]{17})", line)
        if match:
            table[match.group(1)] = match.group(2).upper()
    return table


_vendor_cache = None


def vendor_lookup(mac):
    global _vendor_cache
    if _vendor_cache is None:
        _vendor_cache = {}
        for path in ("/usr/share/nmap/nmap-mac-prefixes", "/usr/local/share/nmap/nmap-mac-prefixes"):
            if os.path.exists(path):
                try:
                    with open(path, encoding="utf-8", errors="ignore") as handle:
                        for line in handle:
                            if line.startswith("#") or len(line) < 8:
                                continue
                            parts = line.strip().split(None, 1)
                            if len(parts) == 2:
                                _vendor_cache[parts[0].upper()] = parts[1]
                    break
                except OSError:
                    continue
    return _vendor_cache.get(mac.replace(":", "").upper()[:6], "")


def parse_xml(xml_text, info, admin):
    root = ET.fromstring(xml_text)
    arp = arp_table()
    rows = []
    for host in root.findall("host"):
        status_node = host.find("status")
        if status_node is None or status_node.get("state") != "up":
            continue
        ip = mac = vendor = ""
        for addr in host.findall("address"):
            kind = addr.get("addrtype")
            if kind == "ipv4":
                ip = addr.get("addr", "")
            elif kind == "mac":
                mac = addr.get("addr", "").upper()
                vendor = addr.get("vendor", "")
        if not mac:
            mac = arp.get(ip, "")
            if not mac and info and ip == info.get("ip"):
                mac = info.get("mac", "")
        if mac and not vendor:
            vendor = vendor_lookup(mac)

        hostnames = [x.get("name") for x in host.findall("hostnames/hostname") if x.get("name")]
        name = hostnames[0] if hostnames else ""
        if info:
            if ip == info.get("gateway"):
                name = (name + " (Modem)").strip()
            elif ip == info.get("ip"):
                name = (name + " (Bu bilgisayar)").strip()

        os_match = host.find("os/osmatch")
        if os_match is not None:
            os_text = f"{os_match.get('name', 'Bilinmiyor')} ({os_match.get('accuracy', '?')}%)"
        else:
            os_text = "Bilinmiyor" if admin else "Bilinmiyor (yönetici yetkisiyle daha iyi sonuç alınabilir)"

        ports = []
        details = []
        for port in host.findall("ports/port"):
            state = port.find("state")
            if state is None or state.get("state") != "open":
                continue
            service_node = port.find("service")
            service = service_node.get("name", "?") if service_node is not None else "?"
            ports.append(f"{port.get('portid', '?')}/{service}")
            extra = ""
            if service_node is not None:
                extra = " ".join(x for x in (service_node.get("product"), service_node.get("version")) if x)
            details.append(f"{port.get('portid')}/{port.get('protocol')}  {service}  {extra}".rstrip())

        rows.append({
            "ip": ip, "name": name or "—", "mac": mac or "—",
            "vendor": vendor or "—", "os": os_text,
            "ports": ", ".join(ports) if ports else "—",
            "tooltip": "\n".join(details),
        })
    rows.sort(key=lambda row: ipaddress.ip_address(row["ip"]) if row["ip"] else ipaddress.ip_address("0.0.0.0"))
    return rows


