class MetricCard(QFrame):
    def __init__(self, label, value="0"):
        super().__init__()
        self.setObjectName("metric")
        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 9, 12, 9)
        layout.setSpacing(3)
        self.value_label = QLabel(value)
        self.value_label.setObjectName("metricValue")
        self.caption = QLabel(label.upper())
        self.caption.setObjectName("metricLabel")
        layout.addWidget(self.value_label)
        layout.addWidget(self.caption)

    def set_value(self, value):
        self.value_label.setText(str(value))


class ScanThread(QThread):
    progress = pyqtSignal(int)
    status = pyqtSignal(str)
    log_line = pyqtSignal(str)
    finished_ok = pyqtSignal(list, float)
    failed = pyqtSignal(str)

    def __init__(self, target, admin, info, profile, custom_ports):
        super().__init__()
        self.target = target
        self.admin = admin
        self.info = info
        self.profile = profile
        self.custom_ports = custom_ports
        self.proc = None
        self.stopped = False

    def stop(self):
        self.stopped = True
        if self.proc and self.proc.poll() is None:
            try:
                self.proc.terminate()
            except OSError:
                pass

    def run(self):
        nmap = shutil.which("nmap")
        if not nmap:
            self.failed.emit("nmap bulunamadı.\nKurmak için: sudo apt update && sudo apt install nmap")
            return
        cmd = []
        if self.admin and os.geteuid() != 0:
            pkexec = shutil.which("pkexec")
            if not pkexec:
                self.failed.emit("pkexec bulunamadı.\nKurmak için: sudo apt install policykit-1")
                return
            cmd.append(pkexec)
        cmd += [nmap, "-T3", "--stats-every", "2s", "-oX", "-"]
        profile_args = {
            "Quick Scan": ["-F", "-sV", "--version-light"],
            "Full Scan (Top 1000)": ["-sV", "--version-light"],
            "Full Scan (All Ports)": ["-p-", "-sV", "--version-light"],
            "Service Detection": ["-sV", "--version-all"],
            "OS Detection": ["-F", "-sV", "--version-light", "-O", "--osscan-guess"],
            "Custom": ["-sV", "--version-light"],
        }
        cmd += profile_args.get(self.profile, profile_args["Quick Scan"])
        if self.custom_ports:
            # Custom port list takes precedence over the profile's default port range.
            cmd = [arg for arg in cmd if arg not in ("-F", "-p-")]
            cmd += ["-p", self.custom_ports]
        if self.admin and "-O" not in cmd:
            cmd += ["-O", "--osscan-guess"]
        elif not self.admin:
            cmd += [UNPRIV_PROBES]
        cmd.append(self.target)
        self.status.emit(f"Taranıyor: {self.target}")
        self.log_line.emit("Komut: " + " ".join(cmd))
        started = datetime.now()
        try:
            self.proc = subprocess.Popen(
                cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, encoding="utf-8", errors="replace", bufsize=1
            )
            lines = []
            if self.proc.stdout:
                for line in self.proc.stdout:
                    if self.stopped:
                        break
                    lines.append(line)
                    match = re.search(r'<taskprogress[^>]*percent="(\d+(?:\.\d+)?)"', line)
                    if match:
                        self.progress.emit(max(0, min(100, int(float(match.group(1))))))
                    stripped = line.strip()
                    if stripped and not stripped.startswith("<"):
                        self.log_line.emit(stripped)
            if self.stopped and self.proc.poll() is None:
                self.proc.terminate()
                try:
                    self.proc.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    self.proc.kill()
            else:
                self.proc.wait()
        except (OSError, subprocess.SubprocessError) as exc:
            self.failed.emit(f"Nmap çalıştırılamadı: {exc}")
            return
        elapsed = (datetime.now() - started).total_seconds()
        if self.stopped:
            self.failed.emit("Tarama kullanıcı tarafından durduruldu.")
            return
        output = "".join(lines)
        start = output.find("<?xml")
        end = output.rfind("</nmaprun>")
        try:
            if start < 0 or end < 0:
                tail = [line.strip() for line in lines if line.strip() and not line.lstrip().startswith("<")][-8:]
                raise ValueError("\n".join(tail) or "Nmap XML çıktısı alınamadı.")
            rows = parse_xml(output[start:end + len("</nmaprun>")], self.info, self.admin)
        except (ET.ParseError, ValueError, OSError) as exc:
            self.failed.emit(f"Tarama sonucu okunamadı:\n{exc}")
            return
        if self.proc and self.proc.returncode not in (0, None):
            self.log_line.emit(f"Nmap çıkış kodu: {self.proc.returncode}")
        self.progress.emit(100)
        self.finished_ok.emit(rows, elapsed)


